function showView(id){if(id==="coordinator"&&!['coordinator','admin'].includes(state.user.role)){alert(state.lang==='fr'?"Cet espace est réservé aux coordinateurs autorisés.":state.lang==='ko'?"이 영역은 승인된 코디네이터 전용입니다.":"This area is restricted to authorized coordinators.");return}document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));document.querySelectorAll(".nav-item").forEach(v=>v.classList.toggle("active",v.dataset.view===id));document.getElementById(id).classList.add("active");window.scrollTo({top:0,behavior:"smooth"});if(id==="plans")loadSharedPlans();if(id==="coordinator")renderCoordinator()}
function hydrate(){["projectTitle","country","sector","stage","problem","solution","beneficiaries","partners","kpis","sdgs"].forEach(k=>{const e=document.getElementById(k);if(e)e.value=state.plan[k]||""});document.getElementById("coachProblem").value=state.plan.problem;document.getElementById("coachUsers").value=state.plan.beneficiaries;document.getElementById("coachSolution").value=state.plan.solution;document.getElementById("coachCountry").value=state.plan.country}
const calcProgress=()=>Math.round(state.milestones.filter(m=>m.done).length/state.milestones.length*100);
function renderUser(){const role=(roles[state.lang]||roles.en)[state.user.role]||state.user.role;document.getElementById("profile-name").textContent=state.user.name;document.getElementById("profile-meta").textContent=`${state.user.country} · ${role}`;document.getElementById("avatar").textContent=initials(state.user.name);document.querySelectorAll(".coordinator-only").forEach(el=>el.style.display=['coordinator','admin'].includes(state.user.role)?"flex":"none")}
function updateMode(){const b=document.getElementById("data-mode"),n=document.getElementById("demo-banner");if(hasSupabase){b.textContent="LIVE BACKEND";b.className="data-state live";if(n)n.style.display="none"}else{b.textContent=state.lang==='fr'?"DONNÉES DÉMO":state.lang==='ko'?"데모 데이터":"DEMO DATA";b.className="data-state demo";if(n)n.style.display="flex"}}
function renderDashboard(){const p=calcProgress();document.getElementById("dash-project").textContent=state.plan.projectTitle;document.getElementById("dash-solution").textContent=state.plan.solution;document.getElementById("dash-progress").style.width=p+"%";document.getElementById("progress-number").textContent=p+"%";document.getElementById("mission-score-value").textContent=p+"%";document.getElementById("dash-next").textContent=(state.milestones.find(m=>!m.done)||{title:"Completed"}).title;document.getElementById("dash-country").innerHTML=`<span class="country-inline">${flag(state.plan.country)} ${esc(state.plan.country)}</span>`;document.getElementById("stat-milestones").textContent=27+state.milestones.filter(m=>m.done).length;document.getElementById("stat-evidence").textContent=13+state.evidence.length;renderRail()}
function renderRail(){document.getElementById("project-rail").innerHTML=demoPlans.slice(0,3).map(x=>`<article class="rail-project"><div class="rail-project-top">${flag(x.country)}<small>${esc(x.country)} · ${esc(x.sector)}</small></div><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p><footer><span>${esc(x.name)}</span><b>${x.progress}%</b></footer></article>`).join("")}
async function savePlan(){["projectTitle","country","sector","stage","problem","solution","beneficiaries","partners","kpis","sdgs"].forEach(k=>state.plan[k]=document.getElementById(k).value.trim());state.plan.country=normalizeCountry(state.plan.country);saveLocal();if(hasSupabase){try{const {data:{user}}=await sb.auth.getUser();if(user)await sb.from("action_plans").upsert({user_id:user.id,title:state.plan.projectTitle,country:state.plan.country,sector:state.plan.sector,stage:state.plan.stage,problem:state.plan.problem,solution:state.plan.solution,beneficiaries:state.plan.beneficiaries,partners:state.plan.partners,kpis:state.plan.kpis,sdgs:state.plan.sdgs,progress:calcProgress(),updated_at:new Date().toISOString()},{onConflict:"user_id"})}catch(e){console.warn(e)}}renderAll();alert(state.lang==='fr'?"Plan enregistré.":state.lang==='ko'?"실행계획이 저장되었습니다.":"Action Plan saved.")}
function jumpCountry(c){selectedCountry=c;showView("plans");setTimeout(()=>{document.querySelectorAll("#country-tabs button").forEach(b=>b.classList.toggle("active",b.dataset.country===c));renderPlans()},20)}
function selectCountryTab(c,el){selectedCountry=c;document.querySelectorAll("#country-tabs button").forEach(b=>b.classList.remove("active"));el.classList.add("active");renderPlans()}
function renderPlans(arr=demoPlans){const s=document.getElementById("sector-filter").value,q=document.getElementById("project-search").value.trim().toLowerCase();const f=arr.filter(x=>(selectedCountry==='all'||normalizeCountry(x.country)===selectedCountry)&&(s==='all'||x.sector===s)&&(!q||`${x.title} ${x.name} ${x.desc} ${x.country} ${x.sector}`.toLowerCase().includes(q)));document.getElementById("plans-list").innerHTML=f.map(x=>`<div class="project-row"><div class="project-main"><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p></div><div class="project-person">${esc(x.name)}</div><div class="project-country">${flag(x.country)}${esc(normalizeCountry(x.country))}</div><div><span class="sector-tag">${esc(x.sector)}</span></div><div class="project-progress">${Number(x.progress||0)}%</div><button class="connect-btn" onclick="alert('Collaboration interest recorded in demo mode.')">CONNECT</button></div>`).join("")||`<div class="project-row"><div class="project-main"><h3>No matching projects</h3><p>Try another country, sector or keyword.</p></div></div>`}
async function loadSharedPlans(){if(hasSupabase){try{const {data,error}=await sb.from("action_plans").select("*,profiles(full_name)").order("updated_at",{ascending:false}).limit(100);if(!error&&data?.length){renderPlans(data.map(x=>({name:x.profiles?.full_name||"Participant",country:normalizeCountry(x.country),sector:x.sector,title:x.title,desc:x.solution,progress:x.progress||0,stage:x.stage||""})));return}}catch(e){console.warn(e)}}renderPlans(demoPlans)}
function renderMilestones(){document.getElementById("milestone-list").innerHTML=state.milestones.map((m,i)=>`<article class="long-step ${m.done?'done':i===state.milestones.findIndex(x=>!x.done)?'active':''}"><div class="day">${esc(m.day)}</div><div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p></div><button onclick="toggleMilestone(${i})">${m.done?'Completed ✓':'Mark complete'}</button></article>`).join("")}
function toggleMilestone(i){state.milestones[i].done=!state.milestones[i].done;saveLocal();renderAll()}
async function uploadEvidence(){const title=document.getElementById("evidenceTitle").value.trim(),type=document.getElementById("evidenceType").value,note=document.getElementById("evidenceNote").value.trim(),fileObj=document.getElementById("evidenceFile").files[0];if(!title)return alert("Add an evidence title.");const item={title,type,note,fileName:fileObj?fileObj.name:"No file attached",date:new Date().toISOString().slice(0,10)};if(hasSupabase&&fileObj){try{const {data:{user}}=await sb.auth.getUser();if(user){const path=`${user.id}/${Date.now()}-${fileObj.name.replace(/\s+/g,"_")}`;const {error}=await sb.storage.from("evidence").upload(path,fileObj);if(!error)await sb.from("evidence").insert({user_id:user.id,title,type,note,file_path:path,file_name:fileObj.name})}}catch(e){console.warn(e)}}state.evidence.unshift(item);document.getElementById("evidenceTitle").value="";document.getElementById("evidenceNote").value="";document.getElementById("evidenceFile").value="";saveLocal();renderAll()}
function renderEvidence(){document.getElementById("journal-count").textContent=`${state.evidence.length} ${state.evidence.length===1?'entry':'entries'}`;document.getElementById("evidence-list").innerHTML=state.evidence.map(e=>`<article class="journal-entry"><div class="journal-icon">${e.type==='Photo'?'▧':e.type==='Test result'?'↗':'□'}</div><div><small>${esc(e.date)} · ${esc(e.type)} · ${esc(e.fileName)}</small><h3>${esc(e.title)}</h3><p>${esc(e.note)}</p></div></article>`).join("");document.getElementById("storage-hint").style.display=hasSupabase?'none':'block'}
async function runCoach(){const out=document.getElementById("coach-output"),payload={problem:document.getElementById("coachProblem").value,users:document.getElementById("coachUsers").value,solution:document.getElementById("coachSolution").value,country:document.getElementById("coachCountry").value,language:state.lang};out.innerHTML="<span class='answer-label'>KOICA ACTIONHUB COACH</span><h3>Thinking…</h3><p>Building a practical implementation brief.</p>";try{const r=await fetch("/api/coach",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(r.ok){const j=await r.json();if(j.text){out.innerHTML=`<span class="answer-label">${(T[state.lang]||T.en).coachOutput}</span><div>${esc(j.text).replace(/\n/g,"<br>")}</div>`;return}}}catch(e){}localCoach(payload)}
function localCoach(p){const smart=state.lang==='fr'?`Dans les 90 jours, valider et préparer un pilote de la solution avec au moins 20 ${p.users}, en utilisant des retours structurés et des données mesurables.`:state.lang==='ko'?`90일 이내에 최소 20명의 ${p.users}을 대상으로 솔루션을 검증하고 파일럿을 준비하며 구조화된 피드백과 측정 가능한 데이터를 활용합니다.`:`Within 90 days, validate and prepare a pilot of the solution with at least 20 ${p.users}, using structured feedback and measurable data.`;document.getElementById("coach-output").innerHTML=`<span class="answer-label">LOCAL COACH FALLBACK</span><h3>90-day implementation brief</h3><p><b>SMART objective</b><br>${esc(smart)}</p><p><b>KPIs</b><br>• 20+ target users interviewed<br>• 5+ tests or demonstrations<br>• Problem-solution fit score<br>• Pilot partners secured<br>• One technical or commercial performance metric</p><p><b>Milestones</b><br>Day 30 — customer discovery<br>Day 60 — MVP refinement<br>Day 90 — pilot readiness</p><p><b>Risks</b><br>Low adoption → co-design with users<br>Affordability → test leasing/pay-per-use<br>Reliability → begin with a monitored pilot</p>`}
async function renderCoordinator(){if(!['coordinator','admin'].includes(state.user.role))return;const c=document.getElementById("coord-country").value;let arr=demoPlans.filter(x=>c==='all'||normalizeCountry(x.country)===c);if(hasSupabase){try{let q=sb.from("action_plans").select("*,profiles(full_name,country)");if(c!=='all')q=q.eq("country",c);const {data,error}=await q.order("updated_at",{ascending:false});if(!error&&data)arr=data.map(x=>({name:x.profiles?.full_name||"Participant",country:normalizeCountry(x.country||x.profiles?.country),title:x.title,progress:x.progress||0}))}catch(e){console.warn(e)}}document.getElementById("coord-parts").textContent=arr.length;document.getElementById("coord-plans").textContent=arr.length;document.getElementById("coord-risk").textContent=arr.filter(x=>(x.progress||0)<35).length;document.getElementById("coord-evidence").textContent=arr.length+4;document.getElementById("coord-table").innerHTML=arr.map(x=>`<div class="oversight-row"><div>${esc(x.name)}</div><div class="country-cell">${flag(x.country)}${esc(normalizeCountry(x.country))}</div><div>${esc(x.title)}</div><div>${Number(x.progress||0)}%</div><div><span class="dot ${(x.progress||0)<25?'risk':(x.progress||0)<40?'warn':'ok'}"></span>${(x.progress||0)<25?'At risk':(x.progress||0)<40?'Follow-up':'On track'}</div></div>`).join("")}

const INFO_PAGES={
about:`<div class="section-kicker">ABOUT KOICA ACTIONHUB</div><h2>From programme learning to measurable implementation.</h2><p>KOICA ActionHub is a shared implementation platform for participants in the KOICA Youth Leaders Program. It helps participants convert Action Plans into practical milestones, evidence, partnerships and results across Cameroon, Côte d'Ivoire, Ghana, Nigeria and Senegal.</p><h3>What ActionHub is designed to do</h3><ul><li>Keep each participant's Action Plan active after training sessions.</li><li>Make 30/60/90-day implementation progress visible.</li><li>Capture evidence such as interviews, test results, partnerships and field learning.</li><li>Help fellows discover relevant peers across the five-country network.</li><li>Give authorized coordinators a clearer view of where support may be needed.</li></ul><div class="privacy-note"><b>Purpose:</b> ActionHub is intended as an implementation and collaboration tool, not a participant-ranking system.</div>`,
how:`<div class="section-kicker">HOW IT WORKS</div><h2>Four steps from Action Plan to impact.</h2><ol><li><b>Create your Action Plan.</b> Define the problem, target users, proposed solution, stakeholders, KPIs and SDG links.</li><li><b>Implement through the 90-Day Mission.</b> Break the plan into clear checkpoints for validation, refinement and pilot readiness.</li><li><b>Document evidence.</b> Use the Field Journal to capture interviews, test results, field photos, partnership notes and lessons.</li><li><b>Collaborate and learn.</b> Discover other projects in the five-country network and connect around shared sectors, challenges or capabilities.</li></ol><h3>For coordinators</h3><p>Authorized coordinator accounts can see implementation status and support signals for follow-up. The goal is to help participants move forward, not to monitor private activity unnecessarily.</p>`,
privacy:`<div class="section-kicker">PRIVACY & DATA USE</div><h2>Your project data should be useful without being careless.</h2><p>ActionHub stores information needed to support programme implementation: participant profile details, Action Plan content, milestones, collaboration requests, feedback and evidence uploaded by the participant.</p><h3>Who can see what?</h3><ul><li><b>Participants:</b> can access their own Action Plan and evidence. Cohort-visible Action Plans may be discoverable by authenticated fellows for collaboration. Participant email addresses are not exposed to other participants.</li><li><b>Coordinators:</b> may access implementation information needed for programme follow-up, subject to role-based permissions.</li><li><b>Administrators:</b> may access programme data required to maintain the platform and support authorized programme functions.</li></ul><h3>Evidence files</h3><p>Uploaded evidence is stored in a private storage bucket. Access is restricted by authentication and role-based database policies.</p><div class="privacy-note"><b>Important:</b> Do not upload passwords, national ID numbers, bank details, confidential medical information, or documents containing unnecessary sensitive personal data.</div><h3>Participant control</h3><p>ActionHub should collect only information relevant to implementation and collaboration. A fuller formal privacy notice can be issued by the programme before wide cohort rollout.</p>`,
help:`<div class="section-kicker">HELP & USER GUIDE</div><h2>Getting started with KOICA ActionHub.</h2><h3>1. Create or sign in to your account</h3><p>Use your programme email where possible, select your country, and create a participant account. If email confirmation is enabled, confirm your address before signing in.</p><h3>2. Complete your Action Plan</h3><p>Open <b>My Action Plan</b>, review each field, and save the plan. Focus on a problem you can realistically move within 90 days.</p><h3>3. Update your Mission</h3><p>Use the <b>90-Day Mission</b> to mark milestones only when the underlying work has actually been completed.</p><h3>4. Build your Field Journal</h3><p>Add evidence that shows learning or implementation: customer interviews, test results, partnership confirmations, pilot observations and other relevant proof.</p><h3>5. Use the Country Network</h3><p>Search projects by country and sector. Collaboration works best when your message explains what you can contribute and what you need.</p><h3>Need assistance?</h3><p>Use the Feedback function to report a bug, missing feature or confusing workflow.</p>`};
function openInfo(page){document.getElementById("info-content").innerHTML=INFO_PAGES[page]||INFO_PAGES.about;document.getElementById("info-modal").classList.remove("hidden");}
function closeInfo(){document.getElementById("info-modal").classList.add("hidden");}

function openLogin(){document.getElementById("login-modal").classList.remove("hidden")}function closeLogin(){document.getElementById("login-modal").classList.add("hidden")}function openFeedback(){document.getElementById("feedback-modal").classList.remove("hidden")}function closeFeedback(){document.getElementById("feedback-modal").classList.add("hidden")}
function demoLogin(){state.user={name:document.getElementById("login-name").value.trim()||"Participant",email:document.getElementById("login-email").value.trim(),country:normalizeCountry(document.getElementById("login-country").value),role:document.getElementById("login-role").value};saveLocal();renderAll();closeLogin()}
async function realLogin(){if(!hasSupabase)return alert("Supabase is not configured yet.");const email=document.getElementById("login-email").value.trim(),password=document.getElementById("login-password").value;if(!email||!password)return alert("Enter email and password.");const {data,error}=await sb.auth.signInWithPassword({email,password});if(error)return alert(error.message);const {data:profile}=await sb.from("profiles").select("*").eq("id",data.user.id).single();state.user={name:profile?.full_name||email,email,country:normalizeCountry(profile?.country),role:profile?.role||"participant"};saveLocal();renderAll();closeLogin()}
async function realSignUp(){if(!hasSupabase)return alert("Supabase is not configured yet.");const name=document.getElementById("login-name").value.trim()||"Participant",email=document.getElementById("login-email").value.trim(),password=document.getElementById("login-password").value,country=normalizeCountry(document.getElementById("login-country").value);if(!email||!password)return alert("Enter email and password.");const {error}=await sb.auth.signUp({email,password,options:{data:{full_name:name,country,role:"participant"}}});if(error)return alert(error.message);alert("Participant account created. Check your email if confirmation is enabled, then sign in.")}
async function submitFeedback(){const type=document.getElementById("feedback-type").value,rating=Number(document.getElementById("feedback-rating").value),message=document.getElementById("feedback-message").value.trim();if(!message)return alert("Please write a short feedback message.");const item={type,rating,message,user_name:state.user.name,country:state.user.country,created_at:new Date().toISOString()};const saved=JSON.parse(localStorage.getItem("koica-actionhub-feedback")||"[]");saved.unshift(item);localStorage.setItem("koica-actionhub-feedback",JSON.stringify(saved));if(hasSupabase){try{const {data:{user}}=await sb.auth.getUser();await sb.from("feedback").insert({user_id:user?.id||null,type,rating,message,country:state.user.country})}catch(e){console.warn(e)}}document.getElementById("feedback-message").value="";closeFeedback();alert(state.lang==='fr'?"Merci pour votre retour !":state.lang==='ko'?"피드백 감사합니다!":"Thank you for your feedback!")}
function renderUser(){const role=(roles[state.lang]||roles.en)[state.user.role]||state.user.role;document.getElementById("profile-name").textContent=state.user.name;document.getElementById("profile-meta").textContent=`${state.user.country} · ${role}`;document.getElementById("avatar").textContent=initials(state.user.name);document.querySelectorAll(".coordinator-only").forEach(el=>el.style.display=['coordinator','admin'].includes(state.user.role)?'flex':'none')}
function renderAll(){hydrate();applyLanguage();renderUser();updateMode();renderDashboard();renderPlans();renderMilestones();renderEvidence();if(['coordinator','admin'].includes(state.user.role))renderCoordinator()}

// Privacy/session patch: production behavior is account-based; no participant data is used before authentication.
function renderUser(){
  const nameEl=document.getElementById("profile-name"),metaEl=document.getElementById("profile-meta"),avatarEl=document.getElementById("avatar");
  if(!currentSessionUser||!state.user){nameEl.textContent=state.lang==='fr'?"Se connecter":state.lang==='ko'?"로그인":"Sign in";metaEl.textContent=state.lang==='fr'?"Compte participant":state.lang==='ko'?"참가자 계정":"Participant account";avatarEl.textContent="↗";document.querySelectorAll(".coordinator-only").forEach(el=>el.style.display="none");const so=document.getElementById("signout-button");if(so)so.style.display="none";return;}
  const role=(roles[state.lang]||roles.en)[state.user.role]||state.user.role;nameEl.textContent=state.user.name||"Participant";metaEl.textContent=`${state.user.country||""} · ${role}`;avatarEl.textContent=initials(state.user.name||"Participant");document.querySelectorAll(".coordinator-only").forEach(el=>el.style.display=['coordinator','admin'].includes(state.user.role)?"flex":"none");const so=document.getElementById("signout-button");if(so)so.style.display="inline-flex";
}
function showView(id){
  if(id!=="dashboard"&&!currentSessionUser){openLogin();alert(state.lang==='fr'?"Connectez-vous pour accéder à cet espace.":state.lang==='ko'?"이 영역을 사용하려면 로그인하세요.":"Please sign in to access this area.");return;}
  if(id==="coordinator"&&!['coordinator','admin'].includes(state.user?.role)){alert(state.lang==='fr'?"Cet espace est réservé aux coordinateurs autorisés.":state.lang==='ko'?"이 영역은 승인된 코디네이터 전용입니다.":"This area is restricted to authorized coordinators.");return;}
  document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));document.querySelectorAll(".nav-item").forEach(v=>v.classList.toggle("active",v.dataset.view===id));document.getElementById(id).classList.add("active");window.scrollTo({top:0,behavior:"smooth"});if(id==="plans")loadSharedPlans();if(id==="coordinator")renderCoordinator();
}
function hydrate(){["projectTitle","country","sector","stage","problem","solution","beneficiaries","partners","kpis","sdgs"].forEach(k=>{const e=document.getElementById(k);if(e)e.value=state.plan[k]||""});document.getElementById("coachProblem").value=state.plan.problem||"";document.getElementById("coachUsers").value=state.plan.beneficiaries||"";document.getElementById("coachSolution").value=state.plan.solution||"";if(state.plan.country)document.getElementById("coachCountry").value=state.plan.country;}
function renderDashboard(){
  const signed=Boolean(currentSessionUser&&state.user),p=signed?calcProgress():0;document.getElementById("dash-project").textContent=signed?(state.plan.projectTitle||"No Action Plan yet"):(state.lang==='fr'?"Connectez-vous pour voir votre plan":state.lang==='ko'?"실행계획을 보려면 로그인하세요":"Sign in to view your Action Plan");document.getElementById("dash-solution").textContent=signed?(state.plan.solution||"Start your Action Plan to define the change you want to implement."):"Your personal Action Plan, milestones and evidence appear only after you sign in.";document.getElementById("dash-progress").style.width=p+"%";document.getElementById("progress-number").textContent=p+"%";document.getElementById("mission-score-value").textContent=p+"%";document.getElementById("dash-next").textContent=signed?((state.milestones.find(m=>!m.done)||{title:"Completed"}).title):"Sign in";document.getElementById("dash-country").innerHTML=signed&&state.plan.country?`<span class="country-inline">${flag(state.plan.country)} ${esc(state.plan.country)}</span>`:"—";document.getElementById("stat-milestones").textContent=signed?state.milestones.filter(m=>m.done).length:0;document.getElementById("stat-evidence").textContent=signed?state.evidence.length:0;renderRail();
}
function renderRail(){const rail=document.getElementById("project-rail");if(!currentSessionUser){rail.innerHTML=`<article class="rail-project"><h3>Sign in to explore cohort projects</h3><p>Country Network information is available only to authenticated participants.</p></article>`;return;}const arr=sharedPlans.slice(0,3);rail.innerHTML=arr.length?arr.map(x=>`<article class="rail-project"><div class="rail-project-top">${flag(x.country)}<small>${esc(x.country)} · ${esc(x.sector||"")}</small></div><h3>${esc(x.title)}</h3><p>${esc(x.desc||"")}</p><footer><span>${esc(x.name)}</span><b>${Number(x.progress||0)}%</b></footer></article>`).join(""):`<article class="rail-project"><h3>No cohort projects yet</h3><p>Saved cohort-visible Action Plans will appear here.</p></article>`;}
function renderPlans(arr=sharedPlans){const sector=document.getElementById("sector-filter").value,q=document.getElementById("project-search").value.trim().toLowerCase();const f=(arr||[]).filter(x=>(selectedCountry==='all'||normalizeCountry(x.country)===selectedCountry)&&(sector==='all'||x.sector===sector)&&(!q||`${x.title} ${x.name} ${x.desc} ${x.country} ${x.sector}`.toLowerCase().includes(q)));document.getElementById("plans-list").innerHTML=f.map(x=>`<div class="project-row"><div class="project-main"><h3>${esc(x.title)}</h3><p>${esc(x.desc||"")}</p></div><div class="project-person">${esc(x.name)}</div><div class="project-country">${flag(x.country)}${esc(normalizeCountry(x.country))}</div><div><span class="sector-tag">${esc(x.sector||"")}</span></div><div class="project-progress">${Number(x.progress||0)}%</div><button class="connect-btn" onclick="alert('Collaboration requests will be enabled in the next pilot step.')">CONNECT</button></div>`).join("")||`<div class="project-row"><div class="project-main"><h3>No matching projects</h3><p>Saved cohort-visible projects will appear here.</p></div></div>`;}
async function loadSharedPlans(render=true){if(!currentSessionUser){sharedPlans=[];if(render)renderPlans([]);return;}const {data,error}=await sb.from("action_plans").select("id,title,country,sector,stage,solution,progress,profiles(full_name,country,organization)").eq("visibility","cohort").order("updated_at",{ascending:false}).limit(100);if(error){console.warn(error);sharedPlans=[];}else sharedPlans=(data||[]).map(x=>({name:x.profiles?.full_name||"Participant",country:normalizeCountry(x.country||x.profiles?.country),sector:x.sector||"",title:x.title||"Untitled Action Plan",desc:x.solution||"",progress:x.progress||0,stage:x.stage||""}));if(render)renderPlans(sharedPlans);const active=document.querySelector('.pulse-grid > div:first-child strong');if(active)active.textContent=sharedPlans.length;renderRail();}
async function loadOwnWorkspace(){if(!currentSessionUser||!state.user)return;const {data:plan,error:planError}=await sb.from("action_plans").select("*").eq("user_id",currentSessionUser.id).maybeSingle();if(planError)console.warn(planError);state.plan=plan?{projectTitle:plan.title||"",country:normalizeCountry(plan.country||state.user.country),sector:plan.sector||"",stage:plan.stage||"",problem:plan.problem||"",solution:plan.solution||"",beneficiaries:plan.beneficiaries||"",partners:plan.partners||"",kpis:plan.kpis||"",sdgs:plan.sdgs||""}:{...blankPlan,country:state.user.country};const {data:ms}=plan?await sb.from("milestones").select("*").eq("action_plan_id",plan.id).order("sort_order",{ascending:true}):{data:null};state.milestones=ms?.length?ms.map(m=>({day:m.label||"Checkpoint",title:m.title||"Milestone",desc:m.description||"",done:Boolean(m.completed)})):defaultMilestones.map(x=>({...x}));const {data:ev}=await sb.from("evidence").select("title,type,note,file_name,created_at").eq("user_id",currentSessionUser.id).order("created_at",{ascending:false});state.evidence=(ev||[]).map(e=>({title:e.title,type:e.type,note:e.note||"",fileName:e.file_name||"No file attached",date:(e.created_at||"").slice(0,10)}));}
async function savePlan(){if(!currentSessionUser){openLogin();return;}["projectTitle","sector","stage","problem","solution","beneficiaries","partners","kpis","sdgs"].forEach(k=>state.plan[k]=document.getElementById(k).value.trim());state.plan.country=state.user.country;if(!state.plan.projectTitle)return alert("Add a project title before saving.");const {error}=await sb.from("action_plans").upsert({user_id:currentSessionUser.id,title:state.plan.projectTitle,country:state.plan.country,sector:state.plan.sector,stage:state.plan.stage,problem:state.plan.problem,solution:state.plan.solution,beneficiaries:state.plan.beneficiaries,partners:state.plan.partners,kpis:state.plan.kpis,sdgs:state.plan.sdgs,progress:calcProgress(),status:"active",visibility:"cohort",updated_at:new Date().toISOString()},{onConflict:"user_id"});if(error)return alert(error.message);await loadOwnWorkspace();await loadSharedPlans(false);renderAll();alert(state.lang==='fr'?"Plan enregistré dans ActionHub.":state.lang==='ko'?"실행계획이 ActionHub에 저장되었습니다.":"Action Plan saved to ActionHub.");}
async function uploadEvidence(){if(!currentSessionUser){openLogin();return;}const title=document.getElementById("evidenceTitle").value.trim(),type=document.getElementById("evidenceType").value,note=document.getElementById("evidenceNote").value.trim(),fileObj=document.getElementById("evidenceFile").files[0];if(!title)return alert("Add an evidence title.");let file_path=null,file_name=null;if(fileObj){const path=`${currentSessionUser.id}/${Date.now()}-${fileObj.name.replace(/\s+/g,"_")}`;const {error:uploadError}=await sb.storage.from("evidence").upload(path,fileObj);if(uploadError)return alert(uploadError.message);file_path=path;file_name=fileObj.name;}const {error}=await sb.from("evidence").insert({user_id:currentSessionUser.id,title,type,note,file_path,file_name});if(error)return alert(error.message);document.getElementById("evidenceTitle").value="";document.getElementById("evidenceNote").value="";document.getElementById("evidenceFile").value="";await loadOwnWorkspace();renderAll();}
function renderEvidence(){document.getElementById("journal-count").textContent=`${state.evidence.length} ${state.evidence.length===1?'entry':'entries'}`;document.getElementById("evidence-list").innerHTML=state.evidence.map(e=>`<article class="journal-entry"><div class="journal-icon">${e.type==='Photo'?'▧':e.type==='Test result'?'↗':'□'}</div><div><small>${esc(e.date)} · ${esc(e.type)} · ${esc(e.fileName)}</small><h3>${esc(e.title)}</h3><p>${esc(e.note)}</p></div></article>`).join("");document.getElementById("storage-hint").style.display="none";}
async function syncSession(session){currentSessionUser=session?.user||null;if(!currentSessionUser){state.user=null;state.plan={...blankPlan};state.milestones=defaultMilestones.map(x=>({...x}));state.evidence=[];sharedPlans=[];renderAll();return;}const {data:profile,error}=await sb.from("profiles").select("id,full_name,country,role,organization,bio").eq("id",currentSessionUser.id).single();if(error){console.warn(error);return;}state.user={name:profile.full_name||"Participant",country:normalizeCountry(profile.country),role:profile.role||"participant",organization:profile.organization||""};await loadOwnWorkspace();await loadSharedPlans(false);renderAll();}
async function realLogin(){if(!hasSupabase)return alert("Supabase is not configured yet.");const email=document.getElementById("login-email").value.trim(),password=document.getElementById("login-password").value;if(!email||!password)return alert("Enter email and password.");const {data,error}=await sb.auth.signInWithPassword({email,password});if(error)return alert(error.message);closeLogin();currentSessionUser=data.user||data.session?.user||null;if(currentSessionUser){const meta=currentSessionUser.user_metadata||{};state.user={name:meta.full_name||"Participant",country:normalizeCountry(meta.country||""),role:"participant",organization:""};state.plan={...blankPlan,country:normalizeCountry(meta.country||"")};try{renderAll();}catch(e){console.warn("ActionHub immediate login render:",e);}}try{await syncSession(data.session);}catch(e){console.error("ActionHub session load:",e);alert(state.lang==='fr'?"Connexion réussie, mais le chargement de votre espace a rencontré un problème. Actualisez la page.":state.lang==='ko'?"로그인은 성공했지만 워크스페이스를 불러오는 중 문제가 발생했습니다. 페이지를 새로고침하세요.":"Sign-in succeeded, but your workspace could not finish loading. Please refresh the page.");}}
async function realSignUp(){if(!hasSupabase)return alert("Supabase is not configured yet.");const name=document.getElementById("login-name").value.trim(),email=document.getElementById("login-email").value.trim(),password=document.getElementById("login-password").value,country=normalizeCountry(document.getElementById("login-country").value);if(!name||!email||!password)return alert("Enter your name, email and password.");const {error}=await sb.auth.signUp({email,password,options:{emailRedirectTo:"https://actionhub-prototype.vercel.app",data:{full_name:name,country,role:"participant"}}});if(error)return alert(error.message);alert("Participant account created. Check your email to confirm your address, then sign in.");}
async function realSignOut(){if(sb)await sb.auth.signOut();currentSessionUser=null;state.user=null;sharedPlans=[];state.plan={...blankPlan};state.milestones=defaultMilestones.map(x=>({...x}));state.evidence=[];closeLogin();renderAll();}
function demoLogin(){alert("Demo accounts are disabled. Please sign in or create a participant account.");}
async function submitFeedback(){if(!currentSessionUser){openLogin();return;}const type=document.getElementById("feedback-type").value,rating=Number(document.getElementById("feedback-rating").value),message=document.getElementById("feedback-message").value.trim();if(!message)return alert("Please write a short feedback message.");const {error}=await sb.from("feedback").insert({user_id:currentSessionUser.id,type,rating,message,country:state.user.country});if(error)return alert(error.message);document.getElementById("feedback-message").value="";closeFeedback();alert(state.lang==='fr'?"Merci pour votre retour !":state.lang==='ko'?"피드백 감사합니다!":"Thank you for your feedback!");}
async function renderCoordinator(){if(!currentSessionUser||!['coordinator','admin'].includes(state.user?.role))return;const c=document.getElementById("coord-country").value;let q=sb.from("action_plans").select("id,title,country,progress,profiles(full_name,country)");if(c!=='all')q=q.eq("country",c);const {data,error}=await q.order("updated_at",{ascending:false});const arr=error?[]:(data||[]).map(x=>({name:x.profiles?.full_name||"Participant",country:normalizeCountry(x.country||x.profiles?.country),title:x.title,progress:x.progress||0}));document.getElementById("coord-parts").textContent=arr.length;document.getElementById("coord-plans").textContent=arr.length;document.getElementById("coord-risk").textContent=arr.filter(x=>(x.progress||0)<35).length;document.getElementById("coord-evidence").textContent="—";document.getElementById("coord-table").innerHTML=arr.map(x=>`<div class="oversight-row"><div>${esc(x.name)}</div><div class="country-cell">${flag(x.country)}${esc(normalizeCountry(x.country))}</div><div>${esc(x.title)}</div><div>${Number(x.progress||0)}%</div><div><span class="dot ${(x.progress||0)<25?'risk':(x.progress||0)<40?'warn':'ok'}"></span>${(x.progress||0)<25?'At risk':(x.progress||0)<40?'Follow-up':'On track'}</div></div>`).join("");}
function renderAll(){hydrate();applyLanguage();renderUser();updateMode();renderDashboard();renderPlans(sharedPlans);renderMilestones();renderEvidence();if(currentSessionUser&&state.user&&['coordinator','admin'].includes(state.user.role))renderCoordinator();}
renderAll();
(async()=>{if(hasSupabase){const {data:{session}}=await sb.auth.getSession();try{await syncSession(session);}catch(e){console.error("ActionHub initial session sync:",e);}sb.auth.onAuthStateChange((_e,session)=>{setTimeout(()=>{syncSession(session).catch(e=>console.error("ActionHub auth-state sync:",e));},0);});}})();

// --- Multilingual participant-content translation layer (v1) ---
const AH_TRANSLATION_TARGETS={fr:"French",ko:"Korean"};
const AH_COUNTRY_LABELS={
  en:{"Cameroon":"Cameroon","Côte d'Ivoire":"Côte d'Ivoire","Ghana":"Ghana","Nigeria":"Nigeria","Senegal":"Senegal"},
  fr:{"Cameroon":"Cameroun","Côte d'Ivoire":"Côte d'Ivoire","Ghana":"Ghana","Nigeria":"Nigéria","Senegal":"Sénégal"},
  ko:{"Cameroon":"카메룬","Côte d'Ivoire":"코트디부아르","Ghana":"가나","Nigeria":"나이지리아","Senegal":"세네갈"}
};
const AH_TYPE_LABELS={
  en:{"Photo":"Photo","Document":"Document","Interview note":"Interview note","Test result":"Test result","Partnership":"Partnership"},
  fr:{"Photo":"Photo","Document":"Document","Interview note":"Note d'entretien","Test result":"Résultat de test","Partnership":"Partenariat"},
  ko:{"Photo":"사진","Document":"문서","Interview note":"인터뷰 노트","Test result":"테스트 결과","Partnership":"파트너십"}
};
let ahShowOriginalContent=false;
let ahTranslationBusy=false;
let ahTranslationError="";
let ahTranslationTimer=null;
let ahTranslationCache={};
try{ahTranslationCache=JSON.parse(localStorage.getItem("actionhub-translation-cache-v1")||"{}")||{};}catch(_e){ahTranslationCache={};}

function ahHash(text){let h=2166136261;const s=String(text||"");for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(36)+"-"+s.length;}
function ahCacheKey(text,lang=state.lang){return `${lang}:${ahHash(text)}`;}
function ahCountryLabel(country){return (AH_COUNTRY_LABELS[state.lang]||AH_COUNTRY_LABELS.en)[normalizeCountry(country)]||normalizeCountry(country);}
function ahTypeLabel(type){return (AH_TYPE_LABELS[state.lang]||AH_TYPE_LABELS.en)[type]||type||"";}
function ahTranslated(text){const original=String(text||"");if(!original||state.lang==="en"||ahShowOriginalContent)return original;return ahTranslationCache[ahCacheKey(original)]||original;}
function ahHasTranslation(text){const original=String(text||"");return Boolean(original&&state.lang!=="en"&&!ahShowOriginalContent&&ahTranslationCache[ahCacheKey(original)]&&ahTranslationCache[ahCacheKey(original)]!==original);}
function ahTranslationMark(text){if(!ahHasTranslation(text))return "";const label=state.lang==='fr'?"Traduction IA · original conservé":state.lang==='ko'?"AI 번역 · 원문 보존":"AI translation · original preserved";return `<small class="ah-translation-mark">${label}</small>`;}
function ahDayLabel(day){const s=String(day||"");if(state.lang==='fr')return s.replace(/^Day\s*/i,"Jour ");if(state.lang==='ko')return s.replace(/^Day\s*/i,"일차 ");return s;}
function ahAddTranslationStyles(){if(document.getElementById("ah-translation-styles"))return;const style=document.createElement("style");style.id="ah-translation-styles";style.textContent=`
  .ah-translation-bar{max-width:1240px;margin:14px auto 0;padding:10px 16px;border:1px solid #d8e2ec;background:#f7fafc;display:flex;gap:14px;align-items:center;justify-content:space-between;font-size:13px;color:#334155}
  .ah-translation-bar[hidden]{display:none!important}.ah-translation-bar strong{color:#0f3d66}.ah-translation-bar button{border:1px solid #9fb3c8;background:white;border-radius:4px;padding:7px 11px;font:inherit;cursor:pointer;color:#0f3d66}.ah-translation-bar button:hover{background:#eef5fb}
  .ah-translation-dot{width:8px;height:8px;border-radius:50%;background:#2f80c9;display:inline-block;margin-right:8px}.ah-translation-dot.busy{animation:ahpulse 1s infinite alternate}.ah-translation-dot.error{background:#b45309}@keyframes ahpulse{to{opacity:.25}}
  .ah-translation-mark{display:block;margin-top:7px;color:#64748b;font-size:10px;letter-spacing:.02em}.ah-original-edit-note{margin:0 0 16px;padding:10px 12px;border-left:3px solid #2f80c9;background:#f7fafc;color:#475569;font-size:12px}
  @media(max-width:720px){.ah-translation-bar{margin:8px 12px 0;align-items:flex-start;flex-direction:column}.ah-translation-bar button{width:100%}}
`;document.head.appendChild(style);}
function ahActiveView(){return document.querySelector(".view.active")?.id||"dashboard";}
function ahEnsureTranslationBar(){ahAddTranslationStyles();let bar=document.getElementById("ah-translation-bar");if(!bar){bar=document.createElement("div");bar.id="ah-translation-bar";bar.className="ah-translation-bar";const main=document.querySelector("main.main");if(main)main.parentNode.insertBefore(bar,main);}
  const active=ahActiveView();
  if(!currentSessionUser||state.lang==="en"){bar.hidden=true;return;}
  bar.hidden=false;
  const isEdit=active==="myplan"||active==="coach";
  const target=state.lang==='fr'?"français":"한국어";
  let message;
  if(isEdit){message=state.lang==='fr'?"Vous modifiez toujours le texte original du participant. Les traductions apparaissent dans les vues de lecture et de réseau.":"참가자 입력 내용은 항상 원문으로 편집됩니다. 번역은 읽기 전용 화면과 네트워크 화면에 표시됩니다.";}
  else if(ahTranslationBusy){message=state.lang==='fr'?"Traduction du contenu des participants…":"참가자 콘텐츠를 번역하는 중…";}
  else if(ahTranslationError){message=state.lang==='fr'?"La traduction est temporairement indisponible. Le contenu original reste visible.":"번역을 일시적으로 사용할 수 없습니다. 원문은 계속 표시됩니다.";}
  else if(ahShowOriginalContent){message=state.lang==='fr'?`Affichage du contenu original. L'interface reste en ${target}.`:`원문을 표시하고 있습니다. 인터페이스는 ${target}로 유지됩니다.`;}
  else{message=state.lang==='fr'?"Affichage de traductions françaises lorsque disponibles. Le texte original reste inchangé dans ActionHub.":"사용 가능한 경우 한국어 번역을 표시합니다. ActionHub의 원문 데이터는 변경되지 않습니다.";}
  const dotClass=ahTranslationError?"error":ahTranslationBusy?"busy":"";
  const buttonLabel=ahShowOriginalContent?(state.lang==='fr'?"Voir la traduction":"번역 보기"):(state.lang==='fr'?"Voir l'original":"원문 보기");
  bar.innerHTML=`<div><span class="ah-translation-dot ${dotClass}"></span><strong>${state.lang==='fr'?"Contenu multilingue":"다국어 콘텐츠"}</strong> · ${esc(message)}</div>${isEdit?"":`<button type="button" onclick="ahToggleOriginalContent()">${buttonLabel}</button>`}`;
  ahEnsureEditNote();
}
function ahEnsureEditNote(){const form=document.querySelector("#myplan .workspace-form");if(!form)return;let note=document.getElementById("ah-original-edit-note");if(state.lang==="en"||!currentSessionUser){if(note)note.remove();return;}if(!note){note=document.createElement("div");note.id="ah-original-edit-note";note.className="ah-original-edit-note";const title=form.querySelector(".form-title");if(title)title.insertAdjacentElement("afterend",note);else form.prepend(note);}note.textContent=state.lang==='fr'?"Les champs ci-dessous restent dans la langue originale saisie par le participant. Changer la langue de l'interface ne modifie jamais les données enregistrées.":"아래 입력 필드는 참가자가 작성한 원문 언어로 유지됩니다. 인터페이스 언어를 변경해도 저장된 원문 데이터는 절대 변경되지 않습니다.";}
function ahToggleOriginalContent(){ahShowOriginalContent=!ahShowOriginalContent;renderAll();}
function ahGatherTranslationTexts(){if(!currentSessionUser||state.lang==="en")return[];const active=ahActiveView();let values=[];if(active==="dashboard"){values.push(state.plan.solution,...state.milestones.flatMap(m=>[m.title,m.desc]),...sharedPlans.slice(0,3).flatMap(p=>[p.desc,p.sector,p.stage]));}
  if(active==="plans")values.push(...sharedPlans.slice(0,50).flatMap(p=>[p.desc,p.sector,p.stage]));
  if(active==="challenge")values.push(...state.milestones.flatMap(m=>[m.title,m.desc]));
  if(active==="evidence")values.push(...state.evidence.slice(0,40).flatMap(e=>[e.title,e.note]));
  values=values.map(v=>String(v||"").trim()).filter(v=>v.length>=2&&v.length<=2000);
  return [...new Set(values)].slice(0,40);
}
function ahSaveTranslationCache(){try{const entries=Object.entries(ahTranslationCache);if(entries.length>800)ahTranslationCache=Object.fromEntries(entries.slice(-600));localStorage.setItem("actionhub-translation-cache-v1",JSON.stringify(ahTranslationCache));}catch(_e){} }
function ahScheduleTranslations(delay=80){clearTimeout(ahTranslationTimer);if(!currentSessionUser||state.lang==="en"||ahShowOriginalContent)return;ahTranslationTimer=setTimeout(()=>ahEnsureTranslations(),delay);}
async function ahEnsureTranslations(){if(ahTranslationBusy||!currentSessionUser||state.lang==="en"||ahShowOriginalContent)return;const texts=ahGatherTranslationTexts();const missing=texts.filter(t=>!ahTranslationCache[ahCacheKey(t)]);if(!missing.length){ahTranslationError="";ahEnsureTranslationBar();return;}ahTranslationBusy=true;ahTranslationError="";ahEnsureTranslationBar();try{const {data:{session}}=await sb.auth.getSession();if(!session?.access_token)throw new Error("No authenticated session");const r=await fetch("/api/translate",{method:"POST",headers:{"Content-Type":"application/json","Authorization":`Bearer ${session.access_token}`},body:JSON.stringify({target_language:state.lang,texts:missing})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||"Translation request failed");if(!Array.isArray(j.translations)||j.translations.length!==missing.length)throw new Error("Translation response was incomplete");missing.forEach((text,i)=>{const translated=String(j.translations[i]||"").trim();if(translated)ahTranslationCache[ahCacheKey(text)]=translated;});ahSaveTranslationCache();}catch(e){console.warn("ActionHub translation:",e);ahTranslationError=e.message||"Translation unavailable";}finally{ahTranslationBusy=false;renderAll();}}

// Keep participant-entered data original in editable inputs. Read-only surfaces use translations.
function renderUser(){
  const nameEl=document.getElementById("profile-name"),metaEl=document.getElementById("profile-meta"),avatarEl=document.getElementById("avatar");
  if(!currentSessionUser||!state.user){nameEl.textContent=state.lang==='fr'?"Se connecter":state.lang==='ko'?"로그인":"Sign in";metaEl.textContent=state.lang==='fr'?"Compte participant":state.lang==='ko'?"참가자 계정":"Participant account";avatarEl.textContent="↗";document.querySelectorAll(".coordinator-only").forEach(el=>el.style.display="none");const so=document.getElementById("signout-button");if(so)so.style.display="none";return;}
  const role=(roles[state.lang]||roles.en)[state.user.role]||state.user.role;nameEl.textContent=state.user.name||"Participant";metaEl.textContent=`${ahCountryLabel(state.user.country)} · ${role}`;avatarEl.textContent=initials(state.user.name||"Participant");document.querySelectorAll(".coordinator-only").forEach(el=>el.style.display=['coordinator','admin'].includes(state.user.role)?"flex":"none");const so=document.getElementById("signout-button");if(so)so.style.display="inline-flex";
}
function renderDashboard(){
  const signed=Boolean(currentSessionUser&&state.user),p=signed?calcProgress():0;const solution=signed?(state.plan.solution||""):"";document.getElementById("dash-project").textContent=signed?(state.plan.projectTitle||"No Action Plan yet"):(state.lang==='fr'?"Connectez-vous pour voir votre plan":state.lang==='ko'?"실행계획을 보려면 로그인하세요":"Sign in to view your Action Plan");document.getElementById("dash-solution").innerHTML=signed?(solution?`${esc(ahTranslated(solution))}${ahTranslationMark(solution)}`:(state.lang==='fr'?"Commencez votre plan d'action pour définir le changement que vous souhaitez mettre en œuvre.":state.lang==='ko'?"실행하려는 변화를 정의하려면 실행계획을 시작하세요.":"Start your Action Plan to define the change you want to implement.")):(state.lang==='fr'?"Votre plan personnel, vos jalons et vos preuves apparaissent uniquement après connexion.":state.lang==='ko'?"개인 실행계획, 마일스톤 및 증거는 로그인 후에만 표시됩니다.":"Your personal Action Plan, milestones and evidence appear only after you sign in.");document.getElementById("dash-progress").style.width=p+"%";document.getElementById("progress-number").textContent=p+"%";document.getElementById("mission-score-value").textContent=p+"%";const next=signed?(state.milestones.find(m=>!m.done)||{title:"Completed"}).title:"";document.getElementById("dash-next").textContent=signed?ahTranslated(next):(state.lang==='fr'?"Se connecter":state.lang==='ko'?"로그인":"Sign in");document.getElementById("dash-country").innerHTML=signed&&state.plan.country?`<span class="country-inline">${flag(state.plan.country)} ${esc(ahCountryLabel(state.plan.country))}</span>`:"—";document.getElementById("stat-milestones").textContent=signed?state.milestones.filter(m=>m.done).length:0;document.getElementById("stat-evidence").textContent=signed?state.evidence.length:0;renderRail();
}
function renderRail(){const rail=document.getElementById("project-rail");if(!currentSessionUser){rail.innerHTML=`<article class="rail-project"><h3>${state.lang==='fr'?"Connectez-vous pour explorer les projets de la cohorte":state.lang==='ko'?"코호트 프로젝트를 보려면 로그인하세요":"Sign in to explore cohort projects"}</h3><p>${state.lang==='fr'?"Les informations du Réseau des pays sont réservées aux participants authentifiés.":state.lang==='ko'?"국가 네트워크 정보는 인증된 참가자만 볼 수 있습니다.":"Country Network information is available only to authenticated participants."}</p></article>`;return;}const arr=sharedPlans.slice(0,3);rail.innerHTML=arr.length?arr.map(x=>`<article class="rail-project"><div class="rail-project-top">${flag(x.country)}<small>${esc(ahCountryLabel(x.country))} · ${esc(ahTranslated(x.sector||""))}</small></div><h3>${esc(x.title)}</h3><p>${esc(ahTranslated(x.desc||""))}</p>${ahTranslationMark(x.desc)}<footer><span>${esc(x.name)}</span><b>${Number(x.progress||0)}%</b></footer></article>`).join(""):`<article class="rail-project"><h3>${state.lang==='fr'?"Aucun projet de cohorte pour le moment":state.lang==='ko'?"아직 코호트 프로젝트가 없습니다":"No cohort projects yet"}</h3><p>${state.lang==='fr'?"Les plans visibles par la cohorte apparaîtront ici.":state.lang==='ko'?"코호트 공개 실행계획이 여기에 표시됩니다.":"Saved cohort-visible Action Plans will appear here."}</p></article>`;}
function renderPlans(arr=sharedPlans){const sector=document.getElementById("sector-filter").value,q=document.getElementById("project-search").value.trim().toLowerCase();const f=(arr||[]).filter(x=>(selectedCountry==='all'||normalizeCountry(x.country)===selectedCountry)&&(sector==='all'||x.sector===sector)&&(!q||`${x.title} ${x.name} ${x.desc} ${x.country} ${x.sector}`.toLowerCase().includes(q)));document.getElementById("plans-list").innerHTML=f.map(x=>`<div class="project-row"><div class="project-main"><h3>${esc(x.title)}</h3><p>${esc(ahTranslated(x.desc||""))}</p>${ahTranslationMark(x.desc)}</div><div class="project-person">${esc(x.name)}</div><div class="project-country">${flag(x.country)}${esc(ahCountryLabel(x.country))}</div><div><span class="sector-tag">${esc(ahTranslated(x.sector||""))}</span></div><div class="project-progress">${Number(x.progress||0)}%</div><button class="connect-btn" onclick="alert('Collaboration requests will be enabled in the next pilot step.')">CONNECT</button></div>`).join("")||`<div class="project-row"><div class="project-main"><h3>${state.lang==='fr'?"Aucun projet correspondant":state.lang==='ko'?"일치하는 프로젝트가 없습니다":"No matching projects"}</h3><p>${state.lang==='fr'?"Les projets visibles par la cohorte apparaîtront ici.":state.lang==='ko'?"코호트 공개 프로젝트가 여기에 표시됩니다.":"Saved cohort-visible projects will appear here."}</p></div></div>`;}
function renderMilestones(){const complete=state.lang==='fr'?"Terminé ✓":state.lang==='ko'?"완료 ✓":"Completed ✓";const mark=state.lang==='fr'?"Marquer terminé":state.lang==='ko'?"완료로 표시":"Mark complete";document.getElementById("milestone-list").innerHTML=state.milestones.map((m,i)=>`<article class="long-step ${m.done?'done':i===state.milestones.findIndex(x=>!x.done)?'active':''}"><div class="day">${esc(ahDayLabel(m.day))}</div><div><h3>${esc(ahTranslated(m.title))}</h3><p>${esc(ahTranslated(m.desc))}</p>${ahTranslationMark(m.desc)}</div><button onclick="toggleMilestone(${i})">${m.done?complete:mark}</button></article>`).join("");}
function renderEvidence(){const entryLabel=state.lang==='fr'?(state.evidence.length===1?'entrée':'entrées'):state.lang==='ko'?'개 항목':(state.evidence.length===1?'entry':'entries');document.getElementById("journal-count").textContent=state.lang==='ko'?`${state.evidence.length}${entryLabel}`:`${state.evidence.length} ${entryLabel}`;document.getElementById("evidence-list").innerHTML=state.evidence.map(e=>`<article class="journal-entry"><div class="journal-icon">${e.type==='Photo'?'▧':e.type==='Test result'?'↗':'□'}</div><div><small>${esc(e.date)} · ${esc(ahTypeLabel(e.type))} · ${esc(e.fileName)}</small><h3>${esc(ahTranslated(e.title))}</h3><p>${esc(ahTranslated(e.note))}</p>${ahTranslationMark(e.note)}</div></article>`).join("");document.getElementById("storage-hint").style.display="none";}
function showView(id){
  if(id!=="dashboard"&&!currentSessionUser){openLogin();alert(state.lang==='fr'?"Connectez-vous pour accéder à cet espace.":state.lang==='ko'?"이 영역을 사용하려면 로그인하세요.":"Please sign in to access this area.");return;}
  if(id==="coordinator"&&!['coordinator','admin'].includes(state.user?.role)){alert(state.lang==='fr'?"Cet espace est réservé aux coordinateurs autorisés.":state.lang==='ko'?"이 영역은 승인된 코디네이터 전용입니다.":"This area is restricted to authorized coordinators.");return;}
  document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));document.querySelectorAll(".nav-item").forEach(v=>v.classList.toggle("active",v.dataset.view===id));document.getElementById(id).classList.add("active");window.scrollTo({top:0,behavior:"smooth"});if(id==="plans")loadSharedPlans();if(id==="coordinator")renderCoordinator();ahEnsureTranslationBar();ahScheduleTranslations(120);
}
async function runCoach(){if(!currentSessionUser){openLogin();return;}const out=document.getElementById("coach-output"),payload={problem:document.getElementById("coachProblem").value,users:document.getElementById("coachUsers").value,solution:document.getElementById("coachSolution").value,country:document.getElementById("coachCountry").value,language:state.lang};out.innerHTML="<span class='answer-label'>KOICA ACTIONHUB COACH</span><h3>Thinking…</h3><p>Building a practical implementation brief.</p>";try{const {data:{session}}=await sb.auth.getSession();if(!session?.access_token)throw new Error("No authenticated session");const r=await fetch("/api/coach",{method:"POST",headers:{"Content-Type":"application/json","Authorization":`Bearer ${session.access_token}`},body:JSON.stringify(payload)});if(r.ok){const j=await r.json();if(j.text){out.innerHTML=`<span class="answer-label">${(T[state.lang]||T.en).coachOutput}</span><div>${esc(j.text).replace(/\n/g,"<br>")}</div>`;return}}}catch(e){console.warn("ActionHub coach:",e);}localCoach(payload);}
function renderAll(){hydrate();applyLanguage();renderUser();updateMode();renderDashboard();renderPlans(sharedPlans);renderMilestones();renderEvidence();ahEnsureTranslationBar();if(currentSessionUser&&state.user&&['coordinator','admin'].includes(state.user.role))renderCoordinator();ahScheduleTranslations();}

// Replace the basic language handler with translation-aware behavior.
document.getElementById("language").onchange=async e=>{state.lang=e.target.value;ahShowOriginalContent=false;ahTranslationError="";saveLocal();renderAll();if(state.lang!=="en"&&currentSessionUser)await ahEnsureTranslations();};


// ACTIONHUB LOGIN FIX V3 - resilient authenticated workspace rendering
function ahSafeRenderStep(label, fn){
  try { return fn(); }
  catch (e) { console.error(`ActionHub render step failed: ${label}`, e); return null; }
}

function renderAll(){
  ahSafeRenderStep('hydrate', ()=>hydrate());
  ahSafeRenderStep('language', ()=>applyLanguage());
  ahSafeRenderStep('user', ()=>renderUser());
  ahSafeRenderStep('mode', ()=>updateMode());
  ahSafeRenderStep('dashboard', ()=>renderDashboard());
  ahSafeRenderStep('plans', ()=>renderPlans(sharedPlans));
  ahSafeRenderStep('milestones', ()=>renderMilestones());
  ahSafeRenderStep('evidence', ()=>renderEvidence());
  ahSafeRenderStep('translation bar', ()=>ahEnsureTranslationBar());
  if(currentSessionUser && state.user && ['coordinator','admin'].includes(state.user.role)) {
    Promise.resolve(renderCoordinator()).catch(e=>console.error('ActionHub coordinator render:', e));
  }
  ahSafeRenderStep('translation schedule', ()=>ahScheduleTranslations());
}

async function syncSession(session){
  currentSessionUser=session?.user||null;
  if(!currentSessionUser){
    state.user=null;
    state.plan={...blankPlan};
    state.milestones=defaultMilestones.map(x=>({...x}));
    state.evidence=[];
    sharedPlans=[];
    renderAll();
    return;
  }

  const meta=currentSessionUser.user_metadata||{};
  let profile=null;
  try{
    const result=await sb.from('profiles')
      .select('id,full_name,country,role,organization,bio')
      .eq('id',currentSessionUser.id)
      .single();
    if(result.error) console.warn('ActionHub profile load:', result.error);
    else profile=result.data;
  }catch(e){
    console.warn('ActionHub profile request failed:',e);
  }

  state.user={
    name:profile?.full_name||meta.full_name||'Participant',
    country:normalizeCountry(profile?.country||meta.country||''),
    role:profile?.role||'participant',
    organization:profile?.organization||''
  };

  // Update identity immediately, before loading the rest of the workspace.
  ahSafeRenderStep('authenticated user', ()=>renderUser());

  try{ await loadOwnWorkspace(); }
  catch(e){ console.error('ActionHub own workspace load:',e); }

  try{ await loadSharedPlans(false); }
  catch(e){ console.error('ActionHub cohort load:',e); }

  renderAll();
}

async function realLogin(){
  if(!hasSupabase) return alert('Supabase is not configured yet.');
  const email=document.getElementById('login-email').value.trim();
  const password=document.getElementById('login-password').value;
  if(!email||!password) return alert('Enter email and password.');

  const button=document.querySelector('#login-modal button[onclick="realLogin()"]');
  const oldText=button?.textContent;
  if(button){ button.disabled=true; button.textContent=state.lang==='fr'?'Connexion…':state.lang==='ko'?'로그인 중…':'Signing in…'; }

  try{
    const {data,error}=await sb.auth.signInWithPassword({email,password});
    if(error) return alert(error.message);

    closeLogin();
    currentSessionUser=data.user||data.session?.user||null;
    if(currentSessionUser){
      const meta=currentSessionUser.user_metadata||{};
      state.user={
        name:meta.full_name||'Participant',
        country:normalizeCountry(meta.country||''),
        role:'participant',
        organization:''
      };
      renderAll();
    }

    // Load database-backed workspace without allowing a secondary render error
    // to make a successful sign-in look like a failed sign-in.
    await syncSession(data.session);
  }catch(e){
    console.error('ActionHub sign-in post-processing:',e);
    // Authentication may already have succeeded. Recover from the stored session.
    try{
      const {data:{session}}=await sb.auth.getSession();
      if(session){
        closeLogin();
        await syncSession(session);
        return;
      }
    }catch(recoveryError){
      console.error('ActionHub session recovery:',recoveryError);
    }
    alert(state.lang==='fr'?'Impossible de terminer la connexion. Veuillez réessayer.':state.lang==='ko'?'로그인을 완료할 수 없습니다. 다시 시도해 주세요.':'Unable to finish signing in. Please try again.');
  }finally{
    if(button){ button.disabled=false; button.textContent=oldText||((T[state.lang]||T.en).realLogin); }
  }
}
